<script setup>
import { computed, onMounted, ref } from 'vue'
import Button from 'primevue/button'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import Dialog from 'primevue/dialog'
import InputText from 'primevue/inputtext'
import Message from 'primevue/message'
import Select from 'primevue/select'
import EmptyState from '../../components/EmptyState.vue'
import LoadingState from '../../components/LoadingState.vue'
import PageHeader from '../../components/PageHeader.vue'
import StatusTag from '../../components/StatusTag.vue'
import api, { errorMessage } from '../../services/api'
import { formatDate, labelFor } from '../../utils/status'
const requests = ref([]); const technicians = ref([]); const residents = ref([]); const loading = ref(true); const error = ref(''); const query = ref(''); const status = ref(null); const assignDialog = ref(false); const priorityDialog = ref(false); const selected = ref(null); const technician = ref(null); const priority = ref('NORMAL'); const saving = ref(false); const formError = ref('')
const statuses = ['OPEN', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'CLOSED', 'CANCELLED']; const priorities = ['LOW', 'NORMAL', 'HIGH', 'CRITICAL']
const residentFor = (request) => residents.value.find((item) => item.userId === request.residentUserId)
const residentLabel = (request) => { const resident = residentFor(request); return resident ? `${resident.fullName} · ${resident.apartment?.buildingCode} ${resident.apartment?.unitNumber}` : 'Cư dân' }
const filtered = computed(() => requests.value.filter((item) => (!status.value || item.status === status.value) && `${item.code} ${item.title} ${item.category} ${residentLabel(item)}`.toLowerCase().includes(query.value.toLowerCase())))
const technicianName = (id) => technicians.value.find((item) => item.userId === id)?.fullName || 'Chưa phân công'
const load = async () => { loading.value = true; error.value = ''; try { const [requestResponse, technicianResponse, residentResponse] = await Promise.all([api.get('/management/service-requests'), api.get('/management/technicians'), api.get('/management/residents')]); requests.value = requestResponse.data; technicians.value = technicianResponse.data; residents.value = residentResponse.data } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
const openAssign = (item) => { selected.value = item; technician.value = technicians.value.find((candidate) => candidate.userId === item.assignedTechnicianId) || null; formError.value = ''; assignDialog.value = true }
const assign = async () => { if (!technician.value) { formError.value = 'Vui lòng chọn kỹ thuật viên.'; return }; saving.value = true; formError.value = ''; try { await api.patch(`/management/service-requests/${selected.value.id}/assign`, { technicianId: technician.value.userId }); assignDialog.value = false; await load() } catch (e) { formError.value = errorMessage(e) } finally { saving.value = false } }
const openPriority = (item) => { selected.value = item; priority.value = item.priority; formError.value = ''; priorityDialog.value = true }
const updatePriority = async () => { saving.value = true; formError.value = ''; try { await api.patch(`/management/service-requests/${selected.value.id}/priority`, { priority: priority.value }); priorityDialog.value = false; await load() } catch (e) { formError.value = errorMessage(e) } finally { saving.value = false } }
onMounted(load)
</script>
<template><PageHeader title="Yêu cầu cư dân" description="Tiếp nhận, phân công kỹ thuật viên và theo dõi hạn xử lý." /><section class="content-card"><div class="toolbar"><InputText v-model="query" placeholder="Tìm mã yêu cầu, cư dân hoặc nội dung" /><Select v-model="status" :options="statuses" :option-label="labelFor" placeholder="Tất cả trạng thái" show-clear /></div><LoadingState v-if="loading" /><div v-else-if="error" class="error-panel">{{ error }}</div><EmptyState v-else-if="!filtered.length" icon="pi pi-inbox" title="Chưa có yêu cầu phù hợp" text="Các báo sự cố từ cư dân sẽ hiển thị tại đây." /><DataTable v-else :value="filtered" paginator :rows="10" responsive-layout="scroll"><Column header="Mã"><template #body="{ data }"><strong class="code">{{ data.code }}</strong></template></Column><Column header="Cư dân / căn hộ"><template #body="{ data }">{{ residentLabel(data) }}</template></Column><Column field="title" header="Nội dung" /><Column header="Nhóm"><template #body="{ data }">{{ labelFor(data.category) }}</template></Column><Column header="Ưu tiên"><template #body="{ data }"><StatusTag :value="data.priority" /></template></Column><Column header="Trạng thái"><template #body="{ data }"><StatusTag :value="data.status" /></template></Column><Column header="Kỹ thuật viên"><template #body="{ data }">{{ technicianName(data.assignedTechnicianId) }}</template></Column><Column header="Hạn xử lý"><template #body="{ data }"><span :class="{ overdue: data.overdue }">{{ formatDate(data.dueAt) }}</span></template></Column><Column header="Thao tác"><template #body="{ data }"><div class="card-actions"><Button v-if="data.status === 'OPEN'" label="Phân công" icon="pi pi-user-plus" text @click="openAssign(data)" /><Button v-if="['OPEN', 'ASSIGNED'].includes(data.status)" label="Ưu tiên" icon="pi pi-flag" text @click="openPriority(data)" /></div></template></Column></DataTable></section><Dialog v-model:visible="assignDialog" modal header="Phân công kỹ thuật viên" :style="{ width: 'min(34rem, 94vw)' }"><Message v-if="formError" severity="error">{{ formError }}</Message><div class="field"><label>Kỹ thuật viên <span class="required">*</span></label><Select v-model="technician" :options="technicians" option-label="fullName" placeholder="Chọn kỹ thuật viên" class="full-width"><template #option="slot"><div><strong>{{ slot.option.fullName }}</strong><small class="select-detail">{{ slot.option.email }}</small></div></template><template #value="slot"><span v-if="slot.value">{{ slot.value.fullName }} · {{ slot.value.email }}</span><span v-else>{{ slot.placeholder }}</span></template></Select></div><div class="dialog-footer"><Button label="Hủy" text @click="assignDialog = false" /><Button label="Phân công" :loading="saving" @click="assign" /></div></Dialog><Dialog v-model:visible="priorityDialog" modal header="Cập nhật mức ưu tiên" :style="{ width: 'min(30rem, 94vw)' }"><Message v-if="formError" severity="error">{{ formError }}</Message><div class="field"><label>Mức ưu tiên</label><Select v-model="priority" :options="priorities" :option-label="labelFor" /></div><div class="dialog-footer"><Button label="Hủy" text @click="priorityDialog = false" /><Button label="Lưu thay đổi" :loading="saving" @click="updatePriority" /></div></Dialog></template>
